1	//! Typed calls over one session of the linked checker ([`crate::checker`]). Wire shapes are the ones the official 7.1
2	//! client sends (traced against `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::{Arc, Mutex};
6	use std::time::Duration;
7	
8	use serde::de::DeserializeOwned;
9	use serde::{Deserialize, Serialize};
10	use serde_json::value::RawValue;
11	use serde_json::{Value, json};
12	
13	use crate::checker::{Client, RequestError};
14	
15	/// Why a call failed, split by whether the rest of the run can go on.
16	#[derive(Debug)]
17	pub(crate) enum CallError {
18	    /// The session is gone or stuck: every later call would fail the same way.
19	    Fatal(String),
20	    /// The checker rejected this one call; other components may still resolve.
21	    Rejected(String),
22	    /// The run's heap is past its budget ([`crate::heap`]): the call was not sent, and no later one will be.
23	    OverBudget,
24	}
25	
26	impl std::fmt::Display for CallError {
27	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
28	        match self {
29	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
30	            CallError::OverBudget => f.write_str("the run's heap is past its budget"),
31	        }
32	    }
33	}
34	
35	fn classify(error: RequestError) -> CallError {
36	    match error {
37	        RequestError::Rejected(message) => CallError::Rejected(message),
38	        other => CallError::Fatal(other.to_string()),
39	    }
40	}
41	
42	/// The reference the checker wants back to name a symbol, kept as the JSON text it arrived as: it is opaque to us, and
43	/// is only ever sent back, written into a request as it is.
44	#[derive(Debug, Clone, Deserialize, Serialize)]
45	#[serde(transparent)]
46	pub(crate) struct SymbolRef(Box<RawValue>);
47	
48	impl SymbolRef {
49	    /// The reference's JSON text, which names the symbol within its snapshot.
50	    pub(crate) fn text(&self) -> &str {
51	        self.0.get()
52	    }
53	}
54	
55	#[cfg(test)]
56	impl From<Value> for SymbolRef {
57	    fn from(value: Value) -> Self {
58	        SymbolRef(serde_json::value::to_raw_value(&value).unwrap_or_else(|_| RawValue::NULL.to_owned()))
59	    }
60	}
61	
62	/// What a request asks about besides the snapshot and project [`Rpc`] adds: written as the fields of its parameters, a
63	/// symbol's reference as the text it arrived as.
64	#[derive(Debug, Serialize)]
65	#[serde(untagged)]
66	pub(crate) enum Asking<'a> {
67	    Symbol {
68	        symbol: &'a SymbolRef,
69	    },
70	    Symbols {
71	        symbols: &'a [&'a SymbolRef],
72	    },
73	    /// A declaration, by its node handle.
74	    Location {
75	        location: &'a str,
76	    },
77	    Type {
78	        #[serde(rename = "type")]
79	        type_id: u64,
80	    },
81	    Signatures {
82	        #[serde(rename = "type")]
83	        type_id: u64,
84	        kind: u8,
85	    },
86	    /// A type printed with `TypeFormatFlags`.
87	    Printed {
88	        #[serde(rename = "type")]
89	        type_id: u64,
90	        flags: u64,
91	    },
92	    /// A type or signature, by the handle the checker gave it.
93	    Object {
94	        #[serde(rename = "objectId")]
95	        object_id: u64,
96	    },
97	    File {
98	        file: &'a str,
