184	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
185	/// `[brand]`. An ES-private member is `__#<symbol id>@#<name>`; the source writes `#<name>`. The id is the checker's
186	/// and does not belong in an answer. Takes the escaped name: a name the source writes starting with two underscores
187	/// has a third, so it never matches.
188	fn internal_member_name(escaped: &str) -> Option<String> {
189	    const WELL_KNOWN: [&str; 15] = [
190	        "iterator",
191	        "asyncIterator",
192	        "hasInstance",
193	        "isConcatSpreadable",
194	        "match",
195	        "matchAll",
196	        "replace",
197	        "search",
198	        "species",
199	        "split",
200	        "toPrimitive",
201	        "toStringTag",
202	        "unscopables",
203	        "dispose",
204	        "asyncDispose",
205	    ];
206	    if let Some((id, private)) = escaped.strip_prefix("__#").and_then(|rest| rest.split_once("@#"))
207	        && !id.is_empty()
208	        && id.chars().all(|c| c.is_ascii_digit())
209	    {
210	        return Some(format!("#{private}"));
211	    }
212	    let (symbol, _id) = escaped.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@'))?;
213	    Some(if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") })
214	}
