467	impl Rpc {
468	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
469	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
470	    /// numeric ones.
471	    pub(crate) async fn prepare(
472	        client: &Client,
473	        deadline: Duration,
474	        tsconfig: Option<&str>,
475	    ) -> Result<Value, CallError> {
476	        let rpc = Rpc {
477	            client: client.clone(),
478	            deadline,
479	            snapshot: 0,
480	            project: String::new(),
481	            options: Value::Null,
482	            recording: None,
483	            calls: Arc::default(),
484	            others: Mutex::default(),
485	        };
486	        rpc.call("initialize", &Value::Null).await?;
487	        Ok(match tsconfig {
488	            Some(file) => {
489	                let parsed: Value = decode(&rpc.call("parseConfigFile", &json!({ "file": file })).await?)?;
490	                parsed.get("options").cloned().unwrap_or_else(default_options)
491	            }
492	            None => default_options(),
493	        })
494	    }
