533	    /// A snapshot of its own for a program over `root_files` beside this one's, asked through `client`: derived from
534	    /// this snapshot (`updateSnapshot` with `createPrograms`), it reads every file as this one holds it, from the files
535	    /// this snapshot has read and parsed, and does not go to the disk again. It shares the request counts and the
536	    /// recording; it is released on its own.
537	    async fn beside(&self, client: Client, root_files: &[String]) -> Result<Rpc, CallError> {
538	        let changes = json!({
539	            "createPrograms": [{ "rootFiles": root_files, "compilerOptions": self.options }],
540	            "ensurePrograms": true,
541	        });
542	        let response: SnapshotResponse =
543	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
544	        let rpc = Rpc {
545	            client,
546	            deadline: self.deadline,
547	            snapshot: response.snapshot,
548	            project: String::new(),
549	            options: self.options.clone(),
550	            recording: self.recording.clone(),
551	            calls: self.calls.clone(),
552	            others: Mutex::default(),
553	        };
554	        // The response lists the programs the update made or changed: the one created, not this one's.
555	        let Some(project) = response.projects.into_iter().find(|project| project.id != self.project) else {
556	            // Nothing will hold this snapshot to release it later.
557	            rpc.release().await;
558	            return Err(CallError::Rejected("updateSnapshot created no program".to_string()));
559	        };
560	        Ok(Rpc { project: project.id, ..rpc })
561	    }
