586	    pub(crate) async fn open_in_memory(
587	        client: Client,
588	        deadline: Duration,
589	        options: &Value,
590	        files: &[(String, String)],
591	    ) -> Result<Rpc, CallError> {
592	        let session = Rpc {
593	            client,
594	            deadline,
595	            snapshot: 0,
596	            project: String::new(),
597	            options: options.clone(),
598	            recording: None,
