612	    /// The snapshot after this one with `files` added, held in the checker's memory and never written to disk (each is
613	    /// a root file, keyed by its absolute path), and this one's program rooted at `root_files` and them instead, built at
614	    /// once (`updateSnapshot` with `reconfigurePrograms`). It is derived from this snapshot, so it reads every other file
615	    /// as this one holds it, from the files this one has read and parsed, and holds one program: a fresh `createSnapshot`
616	    /// read and parsed every file again into a second whole program while this one's was still alive. The calls on it
617	    /// count, and are recorded, with this one's; it is released on its own, and this one stays alive until it is.
618	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
619	        let mut roots = root_files.to_vec();
620	        roots.extend(files.iter().map(|(path, _)| path.clone()));
621	        let changes = json!({
622	            "fileSystem": in_memory_layer(files),
623	            "reconfigurePrograms": [{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }],
624	            "ensurePrograms": true,
625	        });
626	        let response: SnapshotResponse =
627	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
628	        // The response lists the projects the update replaced: the reconfigured one, which may keep its id.
629	        let mut projects = response.projects.into_iter().map(|project| project.id);
630	        let project = match projects.len() {
631	            0 => self.project.clone(),
632	            1 => projects.next().unwrap_or_default(),
633	            _ => match projects.find(|id| *id == self.project) {
634	                Some(id) => id,
635	                None => {
636	                    // Nothing will hold this snapshot to release it later.
637	                    self.call("release", &json!({ "snapshot": response.snapshot })).await.ok();
638	                    return Err(CallError::Rejected(
639	                        "updateSnapshot changed programs other than the one reconfigured".to_string(),
640	                    ));
641	                }
642	            },
643	        };
644	        Ok(Rpc {
645	            client: self.client.clone(),
646	            deadline: self.deadline,
647	            snapshot: response.snapshot,
648	            project,
649	            options: self.options.clone(),
650	            recording: self.recording.clone(),
651	            calls: self.calls.clone(),
652	            others: Mutex::default(),
653	        })
654	    }
655	
656	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
657	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
658	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
659	    /// only when it is rebuilt. This snapshot stays alive until it is released.
660	    pub(crate) async fn updated(
661	        &self,
662	        changed: &[String],
663	        deleted: &[String],
664	        roots: Option<&[String]>,
665	    ) -> Result<Rpc, CallError> {
666	        let mut changes = serde_json::Map::new();
667	        if !changed.is_empty() || !deleted.is_empty() {
668	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
669	        }
670	        if let Some(roots) = roots {
671	            changes.insert(
672	                "reconfigurePrograms".to_string(),
673	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
674	            );
675	        }
676	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
677	        let response: SnapshotResponse =
678	            decode(&self.call("updateSnapshot", &json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
679	        // The response lists only the projects it replaced; the synthetic program keeps its id.
680	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
681	        Ok(Rpc {
682	            client: self.client.clone(),
683	            deadline: self.deadline,
684	            snapshot: response.snapshot,
685	            project,
686	            options: self.options.clone(),
687	            recording: self.recording.clone(),
688	            calls: Arc::default(),
689	            others: Mutex::default(),
690	        })
691	    }
692	
693	    /// Runs `work` on the checker thread this session asks ([`Client::run_on_thread`]), given this session as that
694	    /// thread asks it, in place; each request is bounded by this session's deadline.
695	    pub(crate) async fn run_on_thread<T: Send + 'static>(
696	        self: &Arc<Self>,
697	        work: impl FnOnce(Arc<Rpc>) -> T + Send + 'static,
698	    ) -> Result<T, CallError> {
699	        let this = Arc::clone(self);
700	        let run = self.client.run_on_thread(self.deadline, move |client| work(Arc::new(this.through(client))));
701	        run.await.map_err(classify)
702	    }
703	
704	    /// This session asked through `client`: the same snapshot and project, counts and recording.
705	    fn through(&self, client: Client) -> Rpc {
706	        Rpc {
707	            client,
708	            deadline: self.deadline,
709	            snapshot: self.snapshot,
710	            project: self.project.clone(),
711	            options: self.options.clone(),
712	            recording: self.recording.clone(),
713	            calls: self.calls.clone(),
714	            others: Mutex::default(),
715	        }
716	    }
717	
718	    /// The snapshot this session asks about.
719	    #[cfg(test)]
720	    pub(crate) fn snapshot_id(&self) -> u64 {
721	        self.snapshot
722	    }
723	
