729	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
730	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
731	        let response: SnapshotResponse = decode(&self.call("createSnapshot", &params).await?)?;
732	        self.snapshot = response.snapshot;
733	        let Some(project) = response.projects.into_iter().next() else {
734	            // Nothing will hold this snapshot to release it later.
735	            self.release().await;
736	            return Err(CallError::Rejected("createSnapshot returned no project".to_string()));
737	        };
738	        self.project = project.id;
739	        Ok(self)
740	    }
