742	    /// Releases the snapshot, and those of the lanes opened beside it ([`Rpc::open_programs`]).
743	    pub(crate) async fn release(&self) {
744	        let lanes = self.take_lanes();
745	        for snapshot in std::iter::once(self.snapshot).chain(lanes) {
746	            self.call("release", &json!({ "snapshot": snapshot })).await.ok();
747	        }
748	    }
749	
750	    /// Releases the snapshots of the lanes opened beside this one ([`Rpc::open_programs`]) and keeps this one's: what
751	    /// they hold (each lane's program and its checker's caches) is freed before the work that follows the lanes. Each is
752	    /// released once, here or by [`Rpc::release`], never by both. Nothing may ask a lane after.
753	    pub(crate) async fn release_lanes(&self) {
754	        for snapshot in self.take_lanes() {
755	            self.call("release", &json!({ "snapshot": snapshot })).await.ok();
756	        }
757	    }
758	
759	    /// The lanes' snapshots not yet released, which are then no longer this one's to release.
760	    fn take_lanes(&self) -> Vec<u64> {
761	        std::mem::take(&mut *self.others.lock().unwrap_or_else(std::sync::PoisonError::into_inner))
762	    }
763	
764	    /// The recorded calls as a JSON array, or `None` when recording was off.
765	    pub(crate) fn recording(&self) -> Option<Value> {
766	        let log = self.recording.as_ref()?.lock().ok()?;
767	        Some(Value::Array(log.clone()))
768	    }
769	
770	    /// Requests sent so far, by method.
771	    /// The requests inside a batch count under their own methods and in all as `inBatches`, and the batch once as
772	    /// `batchRequests`. It is a profile, not a count of round trips: a batch and its requests are both in it.
773	    pub(crate) fn calls(&self) -> BTreeMap<&'static str, u64> {
774	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
775	    }
776	
777	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
778	    /// expects. The parameters are written straight to the text the checker reads.
779	    async fn call(&self, method: &'static str, params: &impl Serialize) -> Result<Box<RawValue>, CallError> {
780	        // A release gives memory back, so it is sent past the heap budget too.
781	        if method != "release" {
782	            crate::heap::step()?;
783	        }
784	        if let Ok(mut calls) = self.calls.lock() {
785	            *calls.entry(method).or_default() += 1;
786	        }
787	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
788	        let params = serde_json::to_vec(params)
789	            .map_err(|error| CallError::Fatal(format!("failed to serialize a request: {error}")))?;
790	        let Some(log) = &self.recording else {
791	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
792	        };
793	        let sent: Value = serde_json::from_slice(&params).unwrap_or(Value::Null);
794	        let answer = self.client.request_raw(method, params, self.deadline).await.map_err(classify)?;
795	        let (params, result): (Value, Value) = (sent, decode(&answer)?);
796	        if let Ok(mut log) = log.lock() {
797	            log.push(json!({ "method": method, "params": params, "result": result }));
798	        }
799	        Ok(answer)
800	    }
