806	    /// A request about this snapshot and project, its answer left as text.
807	    async fn scoped_text(&self, method: &'static str, extra: Asking<'_>) -> Result<Box<RawValue>, CallError> {
808	        self.call(method, &Scoped { project: &self.project, snapshot: self.snapshot, extra }).await
809	    }
