888	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
889	    /// that may legitimately fail.
890	    pub(crate) async fn batch(
891	        &self,
892	        requests: Vec<(&'static str, Asking<'_>)>,
893	    ) -> Result<Vec<Box<RawValue>>, CallError> {
894	        let wanted = requests.len();
895	        if let Ok(mut calls) = self.calls.lock() {
896	            for (method, _) in &requests {
897	                *calls.entry(method).or_default() += 1;
898	            }
899	            *calls.entry("inBatches").or_default() += wanted as u64;
900	        }
901	        let scoped: Vec<Batched<'_, Asking<'_>>> = requests
902	            .into_iter()
903	            .map(|(method, extra)| Batched {
904	                method,
905	                params: Scoped { project: &self.project, snapshot: self.snapshot, extra },
906	            })
907	            .collect();
908	        let mut answers = Vec::with_capacity(wanted);
909	        let mut token: Option<String> = None;
910	        loop {
911	            let params = BatchParams { requests: &scoped, continuation_token: token.as_deref() };
912	            let page: BatchPage = decode(&self.call("batchRequests", &params).await?)?;
913	            for response in page.responses {
914	                if let Some(error) = response.error {
915	                    return Err(CallError::Rejected(error));
916	                }
917	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
918	            }
919	            match page.continuation_token {
920	                Some(next) => token = Some(next),
921	                None => break,
922	            }
923	        }
924	        if answers.len() != wanted {
925	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
926	        }
927	        Ok(answers)
928	    }
