/// Checks `params`, sent as `name`, against what tsrs reads of it, and the objects nested in it against theirs;
/// returns each mismatch.
fn mismatches(name: &str, params: &Value) -> Vec<String> {
    let Some((_, required, optional)) = TSRS_READS.iter().find(|(known, _, _)| *known == name) else {
        return vec![format!("{name}: not in the table of what tsrs reads")];
    };
    let Some(object) = params.as_object() else {
        return if required.is_empty() && params.is_null() { vec![] } else { vec![format!("{name}: {params}")] };
    };
    let mut wrong: Vec<String> = Vec::new();
    for key in object.keys() {
        if !required.contains(&key.as_str()) && !optional.contains(&key.as_str()) {
            wrong.push(format!("{name}: sends `{key}`, which tsrs does not read"));
        }
    }
    for key in *required {
        if !object.contains_key(*key) {
            wrong.push(format!("{name}: does not send `{key}`"));
        }
    }
    let nested = |key: &str| object.get(key).into_iter().flat_map(|value| value.as_array().cloned().unwrap_or_default());
    if let Some(changes) = object.get("changes") {
        wrong.extend(mismatches("CreateSnapshotParams", changes));
    }
    let changes = object.get("changes").unwrap_or(params);
    if let Some(notified) = changes.get("fileNotifications") {
        wrong.extend(mismatches("FileNotifications", notified));
    }
    for program in changes.get("createPrograms").and_then(Value::as_array).into_iter().flatten() {
        wrong.extend(mismatches("CreateSnapshotProgramParams", program));
    }
    for program in changes.get("reconfigurePrograms").and_then(Value::as_array).into_iter().flatten() {
        wrong.extend(mismatches("ReconfigureSnapshotProgramParams", program));
    }
    for request in nested("requests") {
        wrong.extend(mismatches("BatchRequest", &request));
        wrong.extend(mismatches(request["method"].as_str().unwrap_or_default(), &request["params"]));
    }
    wrong
}

/// Every request a session sends, and every request in its batches, sends exactly the keys tsrs reads for its
/// method: none it ignores, none it needs left out. And every method [`Ask`] names is among them.
#[test]
fn every_key_sent_is_one_tsrs_reads() {
    let sent = sent_by_every_call();
    let wrong: Vec<String> = sent
        .iter()
        .flat_map(|(method, params)| mismatches(method, &serde_json::from_str(params).unwrap()))
        .collect();
    let mut asked: Vec<String> = Vec::new();
    for (method, params) in &sent {
        asked.push(method.clone());
        let params: Value = serde_json::from_str(params).unwrap();
        for request in params.get("requests").and_then(Value::as_array).into_iter().flatten() {
            asked.push(request["method"].as_str().unwrap().to_string());
        }
    }
    let unasked: Vec<&str> = ASKED.iter().copied().filter(|method| !asked.iter().any(|sent| sent == method)).collect();
    let mut named = ASKED.to_vec();
    named.sort_unstable();
    named.dedup();

    assert_eq!(wrong, Vec::<String>::new());
    assert_eq!(unasked, Vec::<&str>::new(), "a method no call sends");
    assert_eq!(named.len(), ASKED.len(), "a method named twice: {ASKED:?}");
}

/// The parameter that chooses the answer is read: a different `kind`, `flags` or `type` gives a different answer
/// from a real checker. (`files` has its own test, `semantic_diagnostics_checks_only_the_requested_file`.)
#[test]
fn each_parameter_that_chooses_the_answer_changes_it() {
    let dir = tempfile::tempdir().unwrap();
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
    let file = root.join("types.ts").to_string();
    let source = "export type Handler = (value?: string) => void;\n\
                  export interface Both { (x: number): string; new (x: string): Both; a: number }\n\
                  export interface Other { b: string }\n\
                  export declare const handler: Handler;\n";
    let files = [(file.clone(), source.to_string())];
    let checker = Backend::start(&root, 1).unwrap();
    let runtime = multi_thread();
    runtime.block_on(async {
        let deadline = Duration::from_secs(30);
        let client = checker.client();
        let options = Rpc::prepare(&client, deadline, None).await.unwrap();
        let rpc = Rpc::open_in_memory(client, deadline, &options, &files).await.unwrap();
        let module = rpc.source_file_symbol(&file).await.unwrap().unwrap();
        let exports = rpc.exports_of_module(&module.reference).await.unwrap();
        let export = |name: &str| exports.iter().find(|symbol| symbol.name == name).unwrap().reference.clone();
        let both = rpc.declared_type_of_symbol(&export("Both")).await.unwrap().id;
        let other = rpc.declared_type_of_symbol(&export("Other")).await.unwrap().id;
        let handler = rpc.type_of_symbol(&export("handler")).await.unwrap().id;
        let returned = async |kind| {
            let mut printed = Vec::new();
            for signature in rpc.signatures(both, kind).await.unwrap() {
                let returns = rpc.return_type(signature.id).await.unwrap().id;
                printed.push(rpc.type_to_string(returns).await.unwrap());
            }
            printed
        };
        let names = async |type_id| {
            rpc.properties(type_id).await.unwrap().into_iter().map(|property| property.name).collect::<Vec<_>>()
        };

        assert_eq!(returned(SignatureKind::Call).await, ["string"]);
        assert_eq!(returned(SignatureKind::Construct).await, ["Both"]);
        assert_eq!(rpc.type_to_string(handler).await.unwrap(), "Handler");
        assert_eq!(rpc.type_to_string_expanded(handler).await.unwrap(), "(value?: string) => void");
        assert_eq!(names(both).await, ["a"]);
        assert_eq!(names(other).await, ["b"]);
        rpc.release().await;
    });
    runtime.block_on(checker.shutdown());
}

