    "/Users/gabe/.cache/caliper/corpora/repos/ant-design/components",
]


def fallback(diags):
    # A checker fallback: code SEMANTIC_BACKEND with severity other than info.
    return [d for d in diags if str(d.get("code", "")).upper() in ("SEMANTIC_BACKEND", "SEMANTICBACKEND") and str(d.get("severity", "")).lower() != "info"]


def walk_diags(value, out):
    if isinstance(value, dict):
        if "code" in value and "severity" in value:
            out.append(value)
        for v in value.values():
            walk_diags(v, out)
    elif isinstance(value, list):
        for v in value:
            walk_diags(v, out)


for corpus in corpora:
    outputs = {"main": [], "branch": []}
    counts = {"main": [], "branch": []}
    for run in range(2):
        for name in (["main", "branch"] if run == 0 else ["branch", "main"]):
            r = subprocess.run([bins[name], "extract", "--src", corpus, "--json", "--quiet", "--no-cache", "-vv"], capture_output=True, text=True)
            data = json.loads(r.stdout)
            data.pop("stats", None)
            diags = []
            walk_diags(data, diags)
            dropped = fallback(diags)
            m = re.findall(r"requests=(\{[^}]*\})", re.sub(r"\x1b\[[0-9;]*m", "", r.stderr))
            counts[name].append(m)
            print(f"{corpus.split('/repos/')[1]} run{run} {name}: exit {r.returncode}, components {len(json.dumps(data))} bytes, fallbacks {len(dropped)}, request lines {len(m)}")
            if not dropped:
                outputs[name].append(json.dumps(data, sort_keys=True))
    same = [a == b for a in outputs["main"] for b in outputs["branch"]]
    print("  output identical (every kept main/branch pair):", same, "kept", len(outputs["main"]), len(outputs["branch"]))
    print("  request counts identical:", [counts["main"][i] == counts["branch"][j] for i in range(2) for j in range(2)])
    print("  counts main run0:", counts["main"][0][:1])

